BASE = 'https://aoaodelivery.com'


def url_of(kind, i):
    if kind in ('page', 'special'): p = PAGE.get(i)
    elif kind == 'post': p = '/blog/' + POST[i] + '/' if i in POST else None
    elif kind == 'term': p = '/product-category/' + TERM[i] + '/' if i in TERM else None
    elif kind == 'product': p = '/product/' + PRODUCT[i] + '/' if i in PRODUCT else None
    else: p = None
    return (BASE + p, BASE + '/en' + p) if p else ('', '')
